Definition tte_side (m1 : mem) (P E lo shi : Z) (n : Z) (g : bool) : Prop :=
  ACONST m1 /\ stack0 m1 lo shi /\ AXStatics m1 /\ AHttpCat m1 g
  /\ accessible m1 P n /\ accessible m1 E 24 /\ shvis m1 E (E + 24).

(* [comment removed for export] *)
Definition tte_win (E : Z) (iv : Z * Z) : Prop := aceil <= fst iv \/ (E <= fst iv /\ snd iv <= E + 24).
