(* [comment removed for export] *)
Local Ltac tte_assign_exit e loc :=
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m m1 P T E lo shi bs E0 g tj junk;
  intros CTX PURE;
  (* [comment removed for export] *)
  destruct CTX as (FRlo & FRhi & TL & EC & ST & WIN & MU & WM & MI & SIDE);
  destruct PURE as (EOK & LO & CEIL & APP & PHI & TLO & THI & TAL & APE & EAL & PE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (stack0_bounds _ _ _ (proj1 (proj2 SIDE))) as [SKB1 SKB2];
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  unfold ErrCodeCells in EC;
