(* [comment removed for export] *)
Lemma tte_b1_low : forall c, 0 <= c < 32 ->
  negb (bv_ltu (Z_to_bv 64 (c + -32)) (Z_to_bv 64 95)) = true.
Proof.
  intros c Hc. unfold bv_ltu. rewrite unsigned_lit_wrap. rewrite unsigned_lit by lia.
  replace ((c + -32) mod 2 ^ 64) with (2^64 + c - 32) by (Z.div_mod_to_equations; lia).
  apply Bool.negb_true_iff. apply Z.ltb_ge. lia.
Qed.
Lemma tte_b1_print : forall c, 32 <= c < 127 ->
  negb (bv_ltu (Z_to_bv 64 (c + -32)) (Z_to_bv 64 95)) = false.
Proof. intros c Hc. unfold bv_ltu. rewrite !unsigned_lit by lia. apply Bool.negb_false_iff. apply Z.ltb_lt. lia. Qed.
Lemma tte_b1_high : forall c, 127 <= c < 256 ->
  negb (bv_ltu (Z_to_bv 64 (c + -32)) (Z_to_bv 64 95)) = true.
Proof. intros c Hc. unfold bv_ltu. rewrite !unsigned_lit by lia. apply Bool.negb_true_iff. apply Z.ltb_ge. lia. Qed.

(* [comment removed for export] *)
Lemma tte_loop : forall (k j : nat) rax ra sp gp tp t0 t1 t2 a3 s0v s1v s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj junk : list byte),
  (length bs - j = k)%nat -> (j < length bs)%nat ->
  (forall j' b, (j' < j)%nat -> nth_error bs j' = Some b -> is_ctl (zb b) = false) ->
  tte_ctx m m1 sp s0v s1v s2v s3v ra P T E lo shi bs E0 g tj junk -> tte_pure sp P T E lo shi bs E0 ->
  evt bsegs (tte_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo shi bs E0 g tj m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz (P + Z.of_nat (length bs))) (wz E)
              (wz (P + Z.of_nat j)) (wz (P + Z.of_nat j + 1)) (wz T) a3 (wz 95) (wz 31) (wz 127) (wz 9)
              (wz ASHADOW_BASE) s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xd63b8) fc None m1 (seg_rom bsegs)).
Proof.
